// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(uint160(actor) > 0xffff); // avoid precompiles/system addresses
        amount = bound(amount, 1, 1e18);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool depOk, ) = address(c).call{value: amount}("");
        assertTrue(depOk);
        vm.prank(actor);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(ok && c.balances(actor) == 0 && address(c).balance == 0);
    }
}
